void Solver::restart() {
    // Reset LBD statistics
    fast_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;
    slow_lbd_sum = 0;

    // Backtrack to root level
    backtrack(0);

    // Reset activity increment to avoid overflow and give fresh decay
    var_inc = 1.0;

    // Rephase variables: use recent best, opposite, or random with new probabilities
    int r = rand() % 100;
    if (r < 50) {
        // 50% chance: keep the best phase seen so far
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 75) {
        // 25% chance: flip the best phase
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        // 25% chance: assign random phase
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }

    // Re‑insert all variables into VSIDS heap to refresh decision order
    for (int i = 1; i <= vars; ++i) {
        if (!vsids.inHeap(i)) vsids.insert(i);
    }
}
